CREATE TABLE IF NOT EXISTS invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NOT NULL,project_id BIGINT UNSIGNED NULL,proposal_id BIGINT UNSIGNED NULL,invoice_number VARCHAR(40) NOT NULL UNIQUE,issue_date DATE NOT NULL, due_date DATE NULL,status ENUM('draft','sent','partially_paid','paid','overdue','cancelled') NOT NULL DEFAULT 'draft',currency VARCHAR(10) NOT NULL DEFAULT 'USD',subtotal DECIMAL(15,2) NOT NULL DEFAULT 0,tax_rate DECIMAL(6,3) NOT NULL DEFAULT 0,tax_amount DECIMAL(15,2) NOT NULL DEFAULT 0,total DECIMAL(15,2) NOT NULL DEFAULT 0,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_invoice_client(client_id),INDEX idx_invoice_project(project_id),INDEX idx_invoice_proposal(proposal_id),CONSTRAINT fk_invoice_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE RESTRICT,CONSTRAINT fk_invoice_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoice_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,description VARCHAR(500) NOT NULL,quantity DECIMAL(12,2) NOT NULL DEFAULT 1,unit_price DECIMAL(15,2) NOT NULL DEFAULT 0,line_total DECIMAL(15,2) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,INDEX idx_invoice_items_invoice(invoice_id),CONSTRAINT fk_invoice_item_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoice_payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(15,2) NOT NULL,method VARCHAR(50) NULL,reference VARCHAR(150) NULL,paid_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_invoice_payments_invoice(invoice_id),CONSTRAINT fk_invoice_payment_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
